<?php
namespace App\Foundation\Console;use App\Foundation\Generation\FilePlan;use App\Foundation\Registry\ProjectRegistry;use App\Foundation\Support\JsonFile;use App\Foundation\Support\Names;
final class DesignRenameCommand extends FoundationCommand{protected $signature='design:rename {from} {to} {--dry-run} {--force}';protected $description='Rename a design manifest and update manifest dependencies.';public function handle(FilePlan $p,ProjectRegistry $r):int{$from=Names::studly($this->argument('from'));$to=Names::studly($this->argument('to'));$found=null;foreach($r->design() as $i){if($i['name']===$from){$found=$i;break;}}if(!$found){$this->error('Not found.');return self::FAILURE;}$type=$found['type'];$plural=$type.'s';$found['name']=$to;unset($found['_file']);$p->write("resources/design/{$plural}/{$to}/{$type}.json",JsonFile::encode($found));$p->delete("resources/design/{$plural}/{$from}/{$type}.json");foreach($r->design() as $i){if(in_array($from,$i['uses']??[],true)){ $i['uses']=array_map(fn($x)=>$x===$from?$to:$x,$i['uses']);$file=str_replace(base_path().'/','',$i['_file']);unset($i['_file']);$p->write($file,JsonFile::encode($i),true);}}$this->warn('Blade implementation names are not automatically renamed; inspect design:uses and update code references.');return $this->runPlan($p,"design:rename {$from} {$to}");}}
